WITH base AS (SELECT * FROM suppliers WHERE LENGTH(supplier_name) < 8 AND city = 'New York' AND LENGTH(supplier_name) >= 11), CountrySummary AS (SELECT country, CASE WHEN rating >= 3.8 THEN 'high' WHEN rating >= 2.1 THEN 'mid' ELSE 'low' END AS rating_bucket, MIN(rating) AS min_rating FROM base GROUP BY country, CASE WHEN rating >= 3.8 THEN 'high' WHEN rating >= 2.1 THEN 'mid' ELSE 'low' END) SELECT * FROM CountrySummary ORDER BY rating_bucket, country LIMIT 3
